import express from 'express';
import { createServer } from 'http';

interface IndexEntry {
  id: string;
  content: string;
  normalized: string;
  timestamp: number;
}

class SearchIndex {
  private entries: Map<string, IndexEntry> = new Map();
  private isShuttingDown = false;
  private pendingWrites: Promise<void>[] = [];

  normalizeForIndex(input: string): string {
    // Step 1: Decode any percent-encoded sequences
    let decoded = input;
    try {
      decoded = decodeURIComponent(input);
    } catch {
      decoded = input;
    }
    // Step 2: Unicode NFC normalization
    decoded = decoded.normalize('NFC');
    // Step 3: Strip control characters but preserve valid content
    decoded = decoded.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '');
    return decoded;
  }

  sanitizeForStorage(input: string): string {
    // Remove potential script/injection vectors from raw input
    return input
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;');
  }

  async addEntry(id: string, rawContent: string): Promise<IndexEntry> {
    if (this.isShuttingDown) {
      throw new Error('Service is shutting down');
    }

    // Normalize first, then sanitize for safe storage and display
    const normalized = this.normalizeForIndex(rawContent);
    const sanitized = this.sanitizeForStorage(normalized);

    const entry: IndexEntry = {
      id,
      content: sanitized,
      normalized: sanitized,
      timestamp: Date.now()
    };

    const writeOp = this.persistEntry(entry);
    this.pendingWrites.push(writeOp);
    await writeOp;

    this.entries.set(id, entry);
    return entry;
  }

  async search(query: string): Promise<IndexEntry[]> {
    const normalizedQuery = this.normalizeForIndex(query);
    const sanitizedQuery = this.sanitizeForStorage(normalizedQuery);
    const results: IndexEntry[] = [];

    for (const [, entry] of this.entries) {
      if (entry.normalized.includes(sanitizedQuery)) {
        results.push(entry);
      }
    }
    return results;
  }

  private async persistEntry(entry: IndexEntry): Promise<void> {
    // Simulate async write
    return new Promise(resolve => setTimeout(resolve, 10));
  }

  async gracefulShutdown(): Promise<void> {
    this.isShuttingDown = true;
    await Promise.all(this.pendingWrites);
    this.entries.clear();
  }
}

const app = express();
const index = new SearchIndex();

app.use(express.json());

app.post('/index', async (req, res) => {
  try {
    const { id, content } = req.body;
    if (!id || !content || typeof id !== 'string' || typeof content !== 'string') {
      return res.status(400).json({ error: 'Invalid input' });
    }
    if (id.length > 64 || content.length > 10000) {
      return res.status(400).json({ error: 'Input too large' });
    }
    const entry = await index.addEntry(id, content);
    res.json({ success: true, entry });
  } catch (e: any) {
    res.status(503).json({ error: e.message });
  }
});

app.get('/search', async (req, res) => {
  const query = req.query.q as string;
  if (!query || typeof query !== 'string') {
    return res.status(400).json({ error: 'Missing query' });
  }
  const results = await index.search(query);
  // Return sanitized content for display in search results page
  const displayResults = results.map(r => ({
    id: r.id,
    snippet: r.normalized.substring(0, 200),
    timestamp: r.timestamp
  }));
  res.json({ results: displayResults });
});

const server = createServer(app);
server.listen(3000);

process.on('SIGTERM', async () => {
  server.close();
  await index.gracefulShutdown();
  process.exit(0);
});

export { SearchIndex };
